insert into page_sections(page_id,type,position,content,settings) select id,'hero',0,'{"eyebrow":{"ar":"استوديو رقمي · تقني · إبداعي","en":"Digital · Technology · Creative studio"},"title":{"ar":"نحوّل أفكارك إلى منتجات رقمية مُتقنة","en":"We turn ideas into precisely crafted digital products"},"subtitle":{"ar":"نصمم ونبرمج المواقع والأنظمة، ونبني الهويات، ونقود النمو الرقمي — بدقة في كل تفصيلة.","en":"We design and build websites and systems, craft brands, and drive digital growth — precise in every detail."},"primary_label":{"ar":"ابدأ مشروعك","en":"Start a project"},"primary_href":"/request","secondary_label":{"ar":"استعرض أعمالنا","en":"See our work"},"secondary_href":"/projects","highlights":[{"text":{"ar":"تسليم على مراحل واضحة","en":"Clear, staged delivery"}},{"text":{"ar":"ملكية كاملة للكود والملفات","en":"You own all code and files"}},{"text":{"ar":"دعم بعد الإطلاق","en":"Post-launch support"}}]}'::jsonb,'{"background":"measure"}'::jsonb from pages where slug='home' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='home' and ps.position=0);
insert into page_sections(page_id,type,position,content,settings) select id,'services',1,'{"eyebrow":{"ar":"خدماتنا","en":"Services"},"title":{"ar":"كل ما يحتاجه مشروعك الرقمي","en":"Everything your digital project needs"},"subtitle":{"ar":"من الفكرة والهوية إلى المنتج والنمو.","en":"From idea and identity to product and growth."},"limit":6,"link_label":{"ar":"كل الخدمات","en":"All services"},"link_href":"/services"}'::jsonb,'{"featured_only":true}'::jsonb from pages where slug='home' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='home' and ps.position=1);
insert into page_sections(page_id,type,position,content,settings) select id,'projects',2,'{"eyebrow":{"ar":"أعمالنا","en":"Work"},"title":{"ar":"مشاريع مختارة","en":"Selected projects"},"limit":4,"link_label":{"ar":"كل المشاريع","en":"All projects"},"link_href":"/projects"}'::jsonb,'{"featured_only":true,"layout":"slider"}'::jsonb from pages where slug='home' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='home' and ps.position=2);
insert into page_sections(page_id,type,position,content,settings) select id,'about',3,'{"eyebrow":{"ar":"من نحن","en":"About"},"title":{"ar":"الإتقان طريقة عمل، لا شعار","en":"Precision is how we work, not a slogan"},"body":{"ar":"إتقان فريق من المهندسين والمصممين والمسوقين يجمعهم معيار واحد: أن يُنجز العمل كما يجب. نبدأ من فهم عميق لعملك، ونبني حلولاً قابلة للقياس والتوسع.","en":"ALITQAN is a team of engineers, designers and marketers who share one standard: work done properly. We start with a deep understanding of your business and build measurable, scalable solutions."},"link_label":{"ar":"تعرّف علينا","en":"Get to know us"},"link_href":"/about","highlights":[{"title":{"ar":"فهم قبل التنفيذ","en":"Understand first"},"text":{"ar":"لا نكتب سطراً قبل أن نفهم الهدف.","en":"No code before the goal is clear."}},{"title":{"ar":"جودة قابلة للقياس","en":"Measurable quality"},"text":{"ar":"معايير أداء وأمان واضحة.","en":"Clear performance and security standards."}}]}'::jsonb,'{}'::jsonb from pages where slug='home' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='home' and ps.position=3);
insert into page_sections(page_id,type,position,content,settings) select id,'features',4,'{"eyebrow":{"ar":"لماذا إتقان","en":"Why ALITQAN"},"title":{"ar":"شريك يهتم بالتفاصيل كما تهتم بها","en":"A partner who cares about details as much as you do"},"items":[{"icon":"Ruler","title":{"ar":"دقة في التخطيط","en":"Precise planning"},"text":{"ar":"نطاق واضح وجدول زمني واقعي.","en":"Clear scope and a realistic timeline."}},{"icon":"Gauge","title":{"ar":"أداء وسرعة","en":"Speed & performance"},"text":{"ar":"مواقع وأنظمة سريعة ومستقرة.","en":"Fast, stable sites and systems."}},{"icon":"ShieldCheck","title":{"ar":"أمان من البداية","en":"Secure by default"},"text":{"ar":"حماية البيانات جزء من التصميم.","en":"Data protection is part of the design."}},{"icon":"MessageSquare","title":{"ar":"تواصل شفاف","en":"Transparent communication"},"text":{"ar":"تحديثات منتظمة ونقطة اتصال واحدة.","en":"Regular updates and one point of contact."}}]}'::jsonb,'{"background":"muted","columns":"4"}'::jsonb from pages where slug='home' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='home' and ps.position=4);
insert into page_sections(page_id,type,position,content,settings) select id,'stats',5,'{"eyebrow":{"ar":"بالأرقام","en":"In numbers"},"title":{"ar":"نتائج نفخر بها","en":"Results we are proud of"},"items":[{"value":"120+","label":{"ar":"مشروع منجز","en":"Projects delivered"}},{"value":"40+","label":{"ar":"هوية بصرية","en":"Brand identities"}},{"value":"98%","label":{"ar":"رضا العملاء","en":"Client satisfaction"}},{"value":"8","label":{"ar":"سنوات خبرة","en":"Years of experience"}}]}'::jsonb,'{}'::jsonb from pages where slug='home' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='home' and ps.position=5);
insert into page_sections(page_id,type,position,content,settings) select id,'process',6,'{"eyebrow":{"ar":"آلية العمل","en":"Process"},"title":{"ar":"من الفكرة إلى الإطلاق بخطوات واضحة","en":"From idea to launch, in clear steps"},"items":[{"title":{"ar":"دراسة الفكرة","en":"Discover the idea"},"text":{"ar":"نفهم أهدافك وجمهورك وسوقك قبل أي قرار.","en":"We understand your goals, audience and market before any decision."}},{"title":{"ar":"التخطيط والتحليل","en":"Plan & analyse"},"text":{"ar":"نطاق واضح، أولويات، وخطة زمنية واقعية.","en":"Clear scope, priorities and a realistic timeline."}},{"title":{"ar":"التصميم","en":"Design"},"text":{"ar":"هوية وتجربة ونماذج أولية تُراجع معك.","en":"Identity, UX and prototypes reviewed with you."}},{"title":{"ar":"التطوير","en":"Build"},"text":{"ar":"تطوير على دفعات قصيرة مع عروض دورية.","en":"Short iterations with regular demos."}},{"title":{"ar":"الاختبار","en":"Test"},"text":{"ar":"اختبار الأداء والأمان والتجربة على كل الأجهزة.","en":"Performance, security and UX tested on every device."}},{"title":{"ar":"الإطلاق والدعم","en":"Launch & support"},"text":{"ar":"نشر، قياس، وتحسين مستمر بعد الإطلاق.","en":"Release, measure and keep improving after launch."}}]}'::jsonb,'{"background":"muted"}'::jsonb from pages where slug='home' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='home' and ps.position=6);
insert into page_sections(page_id,type,position,content,settings) select id,'tech',7,'{"eyebrow":{"ar":"التقنيات","en":"Technology"},"title":{"ar":"أدوات حديثة ومجربة","en":"Modern, proven tools"},"items":["Next.js","React","TypeScript","Node.js","PostgreSQL","Supabase","Tailwind CSS","Figma","Vercel","Docker","GA4","n8n"]}'::jsonb,'{}'::jsonb from pages where slug='home' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='home' and ps.position=7);
