insert into page_sections(page_id,type,position,content,settings) select id,'faq',10,'{"eyebrow":{"ar":"أسئلة شائعة","en":"FAQ"},"title":{"ar":"إجابات سريعة","en":"Quick answers"},"items":[{"question":{"ar":"كم تكلفة المشروع؟","en":"How much does a project cost?"},"answer":{"ar":"تعتمد على النطاق. بعد جلسة الاكتشاف نرسل عرضاً مفصلاً.","en":"It depends on scope. After discovery we send a detailed proposal."}},{"question":{"ar":"هل تعملون مع عملاء خارج المملكة؟","en":"Do you work with clients abroad?"},"answer":{"ar":"نعم، نعمل عن بعد مع عملاء في عدة دول.","en":"Yes, we work remotely with clients in several countries."}},{"question":{"ar":"هل أستطيع تعديل موقعي بنفسي؟","en":"Can I edit my website myself?"},"answer":{"ar":"نعم، نسلّم لوحة تحكم سهلة وتدريباً عليها.","en":"Yes, we deliver an easy CMS and training."}}]}'::jsonb,'{}'::jsonb from pages where slug='home' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='home' and ps.position=10);
insert into page_sections(page_id,type,position,content,settings) select id,'cta',11,'{"title":{"ar":"لديك فكرة؟ لنصنعها بإتقان.","en":"Have an idea? Let''s build it precisely."},"subtitle":{"ar":"أخبرنا عن مشروعك وسنعود إليك خلال يوم عمل.","en":"Tell us about your project and we''ll reply within one business day."},"primary_label":{"ar":"اطلب مشروعك","en":"Request a project"},"primary_href":"/request","secondary_label":{"ar":"تواصل معنا","en":"Contact us"},"secondary_href":"/contact"}'::jsonb,'{"background":"brand"}'::jsonb from pages where slug='home' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='home' and ps.position=11);
insert into pages(slug,kind,title,summary,status,position) values ('about','system','{"ar":"من نحن","en":"About us"}'::jsonb,'{"ar":"قصة إتقان ورؤيتها وقيمها.","en":"ALITQAN''s story, vision and values."}'::jsonb,'published',1) on conflict (slug) do nothing;
insert into page_sections(page_id,type,position,content,settings) select id,'page_header',0,'{"eyebrow":{"ar":"من نحن","en":"About us"},"title":{"ar":"نصنع الأثر بإتقان","en":"We make an impact, precisely"},"subtitle":{"ar":"قصة بدأت بسؤال بسيط: لماذا لا يُنجز العمل الرقمي كما يجب؟","en":"A story that began with a simple question: why isn''t digital work done properly?"}}'::jsonb,'{"background":"measure"}'::jsonb from pages where slug='about' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='about' and ps.position=0);
insert into page_sections(page_id,type,position,content,settings) select id,'image_text',1,'{"eyebrow":{"ar":"قصتنا","en":"Our story"},"title":{"ar":"من فكرة إلى استوديو متكامل","en":"From an idea to a full studio"},"body":{"ar":"بدأت إتقان من إيمان بأن الجودة ليست رفاهية. جمعنا المهندسين والمصممين والمسوقين تحت سقف واحد لنقدم حلولاً متكاملة بمعيار واحد.\n\nاليوم نعمل مع شركات ناشئة ومؤسسات لبناء منتجات رقمية يعتمد عليها.","en":"ALITQAN started from the belief that quality is not a luxury. We brought engineers, designers and marketers under one roof to deliver complete solutions to one standard.\n\nToday we work with startups and organisations to build digital products people rely on."},"image":"/demo/about-story.svg"}'::jsonb,'{"image_side":"end"}'::jsonb from pages where slug='about' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='about' and ps.position=1);
insert into page_sections(page_id,type,position,content,settings) select id,'features',2,'{"eyebrow":{"ar":"الرؤية والرسالة","en":"Vision & mission"},"title":{"ar":"إلى أين نتجه","en":"Where we are heading"},"items":[{"icon":"Eye","title":{"ar":"رؤيتنا","en":"Vision"},"text":{"ar":"أن نكون المرجع العربي الأول في الحلول الرقمية المتقنة.","en":"To be the leading Arab reference for precisely crafted digital solutions."}},{"icon":"Target","title":{"ar":"رسالتنا","en":"Mission"},"text":{"ar":"تمكين الأعمال بمنتجات رقمية دقيقة وقابلة للنمو، تُبنى بشفافية وشراكة.","en":"Empower businesses with precise, scalable digital products built through transparency and partnership."}}]}'::jsonb,'{"columns":"2","background":"muted"}'::jsonb from pages where slug='about' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='about' and ps.position=2);
insert into page_sections(page_id,type,position,content,settings) select id,'features',3,'{"eyebrow":{"ar":"قيمنا","en":"Values"},"title":{"ar":"ما نؤمن به","en":"What we believe in"},"items":[{"icon":"Ruler","title":{"ar":"الإتقان","en":"Precision"},"text":{"ar":"نهتم بالتفاصيل التي لا يراها الآخرون.","en":"We care about details others miss."}},{"icon":"BadgeCheck","title":{"ar":"الأمانة","en":"Integrity"},"text":{"ar":"وعود واقعية والتزام بها.","en":"Realistic promises, kept."}},{"icon":"Sparkles","title":{"ar":"الابتكار","en":"Innovation"},"text":{"ar":"حلول حديثة لا قوالب مكررة.","en":"Modern solutions, not recycled templates."}},{"icon":"Handshake","title":{"ar":"الشراكة","en":"Partnership"},"text":{"ar":"نجاحك هو مقياس نجاحنا.","en":"Your success is our measure."}}]}'::jsonb,'{"columns":"4"}'::jsonb from pages where slug='about' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='about' and ps.position=3);
insert into page_sections(page_id,type,position,content,settings) select id,'process',4,'{"eyebrow":{"ar":"أهدافنا","en":"Goals"},"title":{"ar":"ما نعمل على تحقيقه","en":"What we are working towards"},"items":[{"title":{"ar":"جودة عالمية","en":"World-class quality"},"text":{"ar":"منتجات تنافس أفضل المعايير العالمية.","en":"Products that meet global standards."}},{"title":{"ar":"محتوى عربي رقمي أفضل","en":"Better Arabic digital experiences"},"text":{"ar":"تجارب عربية أصيلة لا مترجمة.","en":"Native Arabic experiences, not translations."}},{"title":{"ar":"علاقات طويلة الأمد","en":"Long-term relationships"},"text":{"ar":"نبقى شريكاً بعد الإطلاق.","en":"We remain a partner after launch."}}]}'::jsonb,'{}'::jsonb from pages where slug='about' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='about' and ps.position=4);
