insert into pages(slug,kind,title,summary,status,position) values ('privacy','legal','{"ar":"سياسة الخصوصية","en":"Privacy policy"}'::jsonb,'{"ar":"كيف نجمع بياناتك ونستخدمها.","en":"How we collect and use your data."}'::jsonb,'published',8) on conflict (slug) do nothing;
insert into page_sections(page_id,type,position,content,settings) select id,'rich_text',0,'{"title":{"ar":"سياسة الخصوصية","en":"Privacy policy"},"body":{"ar":"## البيانات التي نجمعها\nنجمع البيانات التي ترسلها عبر نماذج التواصل وطلب المشاريع فقط (الاسم، البريد، الهاتف، تفاصيل الطلب والمرفقات).\n\n## كيف نستخدمها\nللرد على طلبك والتواصل معك بشأنه. لا نبيع بياناتك ولا نشاركها مع أطراف ثالثة لأغراض تسويقية.\n\n## الحماية والاحتفاظ\nتُخزن البيانات في خوادم آمنة ويصل إليها الموظفون المخولون فقط، ونحتفظ بها للمدة اللازمة لخدمتك.\n\n## حقوقك\nيمكنك طلب الاطلاع على بياناتك أو تصحيحها أو حذفها عبر صفحة التواصل.\n\n*هذا نص نموذجي ويجب مراجعته قانونياً قبل الإطلاق.*","en":"## Data we collect\nOnly what you send through the contact and project request forms (name, email, phone, request details and attachments).\n\n## How we use it\nTo answer your request and contact you about it. We never sell your data or share it with third parties for marketing.\n\n## Protection and retention\nData is stored on secure servers, accessible only to authorised staff, and kept only as long as needed to serve you.\n\n## Your rights\nYou can ask to access, correct or delete your data via the contact page.\n\n*This is template text and must be reviewed by a lawyer before launch.*"}}'::jsonb,'{}'::jsonb from pages where slug='privacy' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='privacy' and ps.position=0);
insert into pages(slug,kind,title,summary,status,position) values ('terms','legal','{"ar":"الشروط والأحكام","en":"Terms & conditions"}'::jsonb,'{"ar":"شروط استخدام خدمات إتقان.","en":"Terms for using ALITQAN services."}'::jsonb,'published',9) on conflict (slug) do nothing;
insert into page_sections(page_id,type,position,content,settings) select id,'rich_text',0,'{"title":{"ar":"الشروط والأحكام","en":"Terms & conditions"},"body":{"ar":"## القبول\nباستخدامك هذا الموقع فإنك توافق على هذه الشروط.\n\n## الخدمات\nتخضع كل خدمة لعرض واتفاقية مستقلة تحدد النطاق والتكلفة والمدة.\n\n## الملكية الفكرية\nمحتوى هذا الموقع ملك لإتقان ما لم يُذكر خلاف ذلك.\n\n*نص نموذجي — يُراجع قانونياً.*","en":"## Acceptance\nBy using this website you agree to these terms.\n\n## Services\nEach service is governed by a separate proposal and agreement defining scope, cost and duration.\n\n## Intellectual property\nThis website''s content belongs to ALITQAN unless stated otherwise.\n\n*Template text — to be reviewed by a lawyer.*"}}'::jsonb,'{}'::jsonb from pages where slug='terms' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='terms' and ps.position=0);
insert into pages(slug,kind,title,summary,status,position) values ('acceptable-use','legal','{"ar":"سياسة الاستخدام","en":"Acceptable use policy"}'::jsonb,'{"ar":"قواعد استخدام الموقع.","en":"Rules for using this website."}'::jsonb,'published',10) on conflict (slug) do nothing;
insert into page_sections(page_id,type,position,content,settings) select id,'rich_text',0,'{"title":{"ar":"سياسة الاستخدام","en":"Acceptable use policy"},"body":{"ar":"يُمنع استخدام الموقع أو نماذجه لإرسال محتوى مسيء أو رسائل مزعجة أو ملفات ضارة، أو محاولة الوصول غير المصرح به إلى أي جزء من الأنظمة.\n\n*نص نموذجي — يُراجع قانونياً.*","en":"You may not use this website or its forms to send abusive content, spam or malicious files, or attempt unauthorised access to any part of our systems.\n\n*Template text — to be reviewed by a lawyer.*"}}'::jsonb,'{}'::jsonb from pages where slug='acceptable-use' and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug='acceptable-use' and ps.position=0);
